#include <stdlib.h>
#include <string.h>

char *join_tags(const char **tags, size_t n) {
  char *out = malloc(64);
  strcpy(out, "tags:");
  for (size_t i = 0; i < n; i++) {
    if (i > 0) strcat(out, ",");
    strcat(out, tags[i]);
  }
  return out;
}

