#include <glib.h>

gchar *join_tags(const char **tags, size_t n) {
  GString *s = g_string_new(NULL);
  g_string_append_printf(s, "tags=%zu:", n);
  for (size_t i = 0; i < n; i++) {
    if (i > 0) g_string_append_c(s, ',');
    g_string_append(s, tags[i]);
  }
  return g_string_free(s, FALSE);
}
